Lemma utf8_valid_f_S f l :
  utf8_valid_f (S f) l =
  match l with
  | [] => true
  | b0 :: _ => let n := Z.to_nat (utf8_trail b0 + 1) in
               if (length l <? n)%nat then false else utf8_legal (firstn n l) && utf8_valid_f f (skipn n l)
  end.
Proof.
