Lemma utf8_valid_cons b t :
  utf8_valid (b :: t) =
    let n := Z.to_nat (utf8_trail b + 1) in
    if (length (b :: t) <? n)%nat then false else utf8_legal (firstn n (b :: t)) && utf8_valid (skipn n (b :: t)).
Proof.
