(* [comment removed for export] *)
Lemma utf8_trail_spec b :
  (b < 192 -> utf8_trail b = 0) /\ (192 <= b < 224 -> utf8_trail b = 1) /\ (224 <= b < 240 -> utf8_trail b = 2)
